import React from 'react';
import { render } from '@testing-library/react-native';

jest.mock('@/src/lib/haptics', () => ({ haptic: { selection: jest.fn() } }));
jest.mock('@expo/vector-icons/Feather', () => {
  const React = require('react');
  const { Text } = require('react-native');
  return ({ name }: { name: string }) => React.createElement(Text, null, `feather:${name}`);
});
jest.mock('@expo/vector-icons/MaterialCommunityIcons', () => {
  const React = require('react');
  const { Text } = require('react-native');
  return ({ name }: { name: string }) => React.createElement(Text, null, `mci:${name}`);
});

import { CustomTabBar, VISIBLE_TAB_NAMES } from '@/components/ui/CustomTabBar';
import { getAppPalette } from '@/src/theme/palette';

const routes = VISIBLE_TAB_NAMES.map((name) => ({ key: `${name}-key`, name, params: undefined, path: undefined }));

function renderTabs(chatUnreadCount?: number, hasUnreadFeed = false) {
  const descriptors = Object.fromEntries(routes.map((route) => [route.key, { options: { title: route.name } }]));
  return render(
    <CustomTabBar
      chatUnreadCount={chatUnreadCount}
      descriptors={descriptors as any}
      dynamicDockGradient={['transparent', 'transparent', 'transparent']}
      feedUnreadIndicatorEnabled
      glossColor="transparent"
      hasUnreadFeed={hasUnreadFeed}
      insets={{ bottom: 0, left: 0, right: 0, top: 0 }}
      navigation={{ emit: jest.fn(() => ({ defaultPrevented: false })), navigate: jest.fn() } as any}
      palette={getAppPalette()}
      responsiveMaxContentWidth={480}
      selectedVisibleRoute="chat"
      state={{ history: [], index: 4, key: 'tabs', routeNames: [...VISIBLE_TAB_NAMES], routes, stale: false, type: 'tab' } as any}
      tabBarHeight={72}
      bottomPadding={8}
    />,
  );
}

describe('Buzzr chat unread badge contract', () => {
  it('shows exact unread counts and announces the full count on the tab', () => {
    const screen = renderTabs(7);
    expect(screen.getByTestId('tab-unread-count-chat')).toHaveTextContent('7');
    expect(screen.getByLabelText('chat, 7 unread')).toBeTruthy();
    expect(screen.getByTestId('tab-button-chat').props.accessibilityState).toEqual({ selected: true });
  });

  it('caps only the visual badge while preserving the full accessible count', () => {
    const screen = renderTabs(120);
    expect(screen.getByTestId('tab-unread-count-chat')).toHaveTextContent('99+');
    expect(screen.getByLabelText('chat, 120 unread')).toBeTruthy();
    expect(screen.getByTestId('tab-unread-count-chat').props.accessibilityElementsHidden).toBe(true);
  });

  it('renders no chat count for zero and preserves the pulse activity dot', () => {
    const screen = renderTabs(0, true);
    expect(screen.queryByTestId('tab-unread-count-chat')).toBeNull();
    expect(screen.getByTestId('tab-unread-dot-pulse')).toBeTruthy();
  });
});
